     1→import fs from 'fs';
     2→import path from 'path';
     3→import os from 'os';
     4→import { execSync } from 'child_process';
     5→import { promisify } from 'util';
     6→import {
     7→  COMMAND_NAME,
     8→  DESCRIPTION,
     9→  EXTENSION_ID,
    10→  EXTENSION_ID_WEBSTORE,
    11→  HOST_NAME,
    12→} from './constant';
    13→import { BrowserType, getBrowserConfig, detectInstalledBrowsers } from './browser-config';
    14→
    15→export const access = promisify(fs.access);
    16→export const mkdir = promisify(fs.mkdir);
    17→export const writeFile = promisify(fs.writeFile);
    18→
    19→/**
    20→ * 打印彩色文本
    21→ */
    22→export function colorText(text: string, color: string): string {
    23→  const colors: Record<string, string> = {
    24→    red: '\x1b[31m',
    25→    green: '\x1b[32m',
    26→    yellow: '\x1b[33m',
    27→    blue: '\x1b[34m',
    28→    reset: '\x1b[0m',
    29→  };
    30→
    31→  return colors[color] + text + colors.reset;
    32→}
    33→
    34→/**
    35→ * Get user-level manifest file path
    36→ */
    37→export function getUserManifestPath(): string {
    38→  if (os.platform() === 'win32') {
    39→    // Windows: %APPDATA%\Google\Chrome\NativeMessagingHosts\
    40→    return path.join(
    41→      process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'),
    42→      'Google',
    43→      'Chrome',
    44→      'NativeMessagingHosts',
    45→      `${HOST_NAME}.json`,
    46→    );
    47→  } else if (os.platform() === 'darwin') {
    48→    // macOS: ~/Library/Application Support/Google/Chrome/NativeMessagingHosts/
    49→    return path.join(
    50→      os.homedir(),
    51→      'Library',
    52→      'Application Support',
    53→      'Google',
    54→      'Chrome',
    55→      'NativeMessagingHosts',
    56→      `${HOST_NAME}.json`,
    57→    );
    58→  } else {
    59→    // Linux: ~/.config/google-chrome/NativeMessagingHosts/
    60→    return path.join(
    61→      os.homedir(),
    62→      '.config',
    63→      'google-chrome',
    64→      'NativeMessagingHosts',
    65→      `${HOST_NAME}.json`,
    66→    );
    67→  }
    68→}
    69→
    70→/**
    71→ * Get system-level manifest file path
    72→ */
    73→export function getSystemManifestPath(): string {
    74→  if (os.platform() === 'win32') {
    75→    // Windows: %ProgramFiles%\Google\Chrome\NativeMessagingHosts\
    76→    return path.join(
    77→      process.env.ProgramFiles || 'C:\\Program Files',
    78→      'Google',
    79→      'Chrome',
    80→      'NativeMessagingHosts',
    81→      `${HOST_NAME}.json`,
    82→    );
    83→  } else if (os.platform() === 'darwin') {
    84→    // macOS: /Library/Google/Chrome/NativeMessagingHosts/
    85→    return path.join('/Library', 'Google', 'Chrome', 'NativeMessagingHosts', `${HOST_NAME}.json`);
    86→  } else {
    87→    // Linux: /etc/opt/chrome/native-messaging-hosts/
    88→    return path.join('/etc', 'opt', 'chrome', 'native-messaging-hosts', `${HOST_NAME}.json`);
    89→  }
    90→}
    91→
    92→/**
    93→ * Get native host startup script file path
    94→ */
    95→export async function getMainPath(): Promise<string> {
    96→  try {
    97→    const packageDistDir = path.join(__dirname, '..');
    98→    const wrapperScriptName = process.platform === 'win32' ? 'run_host.bat' : 'run_host.sh';
    99→    const absoluteWrapperPath = path.resolve(packageDistDir, wrapperScriptName);
   100→    return absoluteWrapperPath;
   101→  } catch (error) {
   102→    console.log(colorText('Cannot find global package path, using current directory', 'yellow'));
   103→    throw error;
   104→  }
   105→}
   106→
   107→/**
   108→ * 确保关键文件具有执行权限
   109→ */
   110→export async function ensureExecutionPermissions(): Promise<void> {
   111→  try {
   112→    const packageDistDir = path.join(__dirname, '..');
   113→
   114→    if (process.platform === 'win32') {
   115→      // Windows 平台处理
   116→      await ensureWindowsFilePermissions(packageDistDir);
   117→      return;
   118→    }
   119→
   120→    // Unix/Linux 平台处理
   121→    const filesToCheck = [
   122→      path.join(packageDistDir, 'index.js'),
   123→      path.join(packageDistDir, 'run_host.sh'),
   124→      path.join(packageDistDir, 'cli.js'),
   125→    ];
   126→
   127→    for (const filePath of filesToCheck) {
   128→      if (fs.existsSync(filePath)) {
   129→        try {
   130→          fs.chmodSync(filePath, '755');
   131→          console.log(
   132→            colorText(`✓ Set execution permissions for ${path.basename(filePath)}`, 'green'),
   133→          );
   134→        } catch (err: any) {
   135→          console.warn(
   136→            colorText(
   137→              `⚠️ Unable to set execution permissions for ${path.basename(filePath)}: ${err.message}`,
   138→              'yellow',
   139→            ),
   140→          );
   141→        }
   142→      } else {
   143→        console.warn(colorText(`⚠️ File not found: ${filePath}`, 'yellow'));
   144→      }
   145→    }
   146→  } catch (error: any) {
   147→    console.warn(colorText(`⚠️ Error ensuring execution permissions: ${error.message}`, 'yellow'));
   148→  }
   149→}
   150→
   151→/**
   152→ * Windows 平台文件权限处理
   153→ */
   154→async function ensureWindowsFilePermissions(packageDistDir: string): Promise<void> {
   155→  const filesToCheck = [
   156→    path.join(packageDistDir, 'index.js'),
   157→    path.join(packageDistDir, 'run_host.bat'),
   158→    path.join(packageDistDir, 'cli.js'),
   159→  ];
   160→
   161→  for (const filePath of filesToCheck) {
   162→    if (fs.existsSync(filePath)) {
   163→      try {
   164→        // 检查文件是否为只读，如果是则移除只读属性
   165→        const stats = fs.statSync(filePath);
   166→        if (!(stats.mode & parseInt('200', 8))) {
   167→          // 检查写权限
   168→          // 尝试移除只读属性
   169→          fs.chmodSync(filePath, stats.mode | parseInt('200', 8));
   170→          console.log(
   171→            colorText(`✓ Removed read-only attribute from ${path.basename(filePath)}`, 'green'),
   172→          );
   173→        }
   174→
   175→        // 验证文件可读性
   176→        fs.accessSync(filePath, fs.constants.R_OK);
   177→        console.log(
   178→          colorText(`✓ Verified file accessibility for ${path.basename(filePath)}`, 'green'),
   179→        );
   180→      } catch (err: any) {
   181→        console.warn(
   182→          colorText(
   183→            `⚠️ Unable to verify file permissions for ${path.basename(filePath)}: ${err.message}`,
   184→            'yellow',
   185→          ),
   186→        );
   187→      }
   188→    } else {
   189→      console.warn(colorText(`⚠️ File not found: ${filePath}`, 'yellow'));
   190→    }
   191→  }
   192→}
   193→
   194→/**
   195→ * Create Native Messaging host manifest content
   196→ */
   197→export async function createManifestContent(): Promise<any> {
   198→  const mainPath = await getMainPath();
   199→
   200→  return {
   201→    name: HOST_NAME,
   202→    description: DESCRIPTION,
