import fs from 'fs';
import os from 'os';
import path from 'path';
import { COMMAND_NAME } from './constant';
import { colorText, tryRegisterUserLevelHost } from './utils';

// Check if this script is run directly
const isDirectRun = require.main === module;

// Detect global installation for both npm and pnpm
function detectGlobalInstall(): boolean {
  // npm uses npm_config_global
  if (process.env.npm_config_global === 'true') {
    return true;
  }

  // Method 1: Check common global npm paths (macOS/Linux)
  // This catches: /usr/local/lib/node_modules/, /usr/lib/node_modules/, ~/.npm-global/, etc.
  const globalNpmPatterns = [
    '/usr/local/lib/node_modules/',
    '/usr/lib/node_modules/',
    '/opt/homebrew/lib/node_modules/',
    '/.npm-global/',
    '/lib/node_modules/',
  ];
  if (globalNpmPatterns.some((pattern) => __dirname.includes(pattern))) {
    return true;
  }

  // Method 2: Check if PNPM_HOME is set and current path contains it
  if (process.env.PNPM_HOME && __dirname.includes(process.env.PNPM_HOME)) {
    return true;
  }

  // Method 3: Check if we're in a global pnpm directory structure
  // pnpm global packages are typically installed in ~/.local/share/pnpm/global/5/node_modules
  // Windows: %APPDATA%\pnpm\global\5\node_modules
  const globalPnpmPatterns =
    process.platform === 'win32'
      ? ['\\pnpm\\global\\', '\\pnpm-global\\', '\\AppData\\Roaming\\pnpm\\']
      : ['/pnpm/global/', '/.local/share/pnpm/', '/pnpm-global/', '/Library/pnpm/'];

  if (globalPnpmPatterns.some((pattern) => __dirname.includes(pattern))) {
    return true;
  }

  // Method 4: Check npm_config_prefix for pnpm
  if (process.env.npm_config_prefix && __dirname.includes(process.env.npm_config_prefix)) {
    return true;
  }

  // Method 5: Windows-specific global installation paths
  if (process.platform === 'win32') {
    const windowsGlobalPatterns = [
      '\\npm\\node_modules\\',
      '\\AppData\\Roaming\\npm\\node_modules\\',
      '\\Program Files\\nodejs\\node_modules\\',
      '\\nodejs\\node_modules\\',
    ];

    if (windowsGlobalPatterns.some((pattern) => __dirname.includes(pattern))) {
      return true;
    }
  }

  // Method 6: Check if npm_lifecycle_event is set (indicates npm script context)
  // During npm install -g, this will be 'postinstall'
  if (process.env.npm_lifecycle_event === 'postinstall' && !__dirname.includes('/node_modules/.pnpm/')) {
    // We're in a postinstall hook, check if it looks like a project directory
    // If there's no package.json nearby with workspaces, it's likely global
    const parentDir = path.resolve(__dirname, '..', '..', '..');
    if (!fs.existsSync(path.join(parentDir, 'package.json'))) {
      return true;
    }
  }

  return false;
}

const isGlobalInstall = detectGlobalInstall();

